<?php require '../config/database.php';auth();$id=(int)$_GET['id'];$s=$pdo->prepare('SELECT * FROM technicians WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)die('غير موجود');if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('UPDATE technicians SET name=?,phone=?,specialty=?,salary=?,status=? WHERE id=?');$s->execute([$_POST['name'],$_POST['phone'],$_POST['specialty'],(float)$_POST['salary'],$_POST['status'],$id]);header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>تعديل فني</h1><form method="post"><label>الاسم</label><input name="name" value="<?=htmlspecialchars($r['name'])?>"><label>الهاتف</label><input name="phone" value="<?=htmlspecialchars($r['phone'])?>"><label>التخصص</label><input name="specialty" value="<?=htmlspecialchars($r['specialty'])?>"><label>الراتب</label><input type="number" step="0.01" name="salary" value="<?=$r['salary']?>"><label>الحالة</label><select name="status"><option value="active">نشط</option><option value="inactive" <?=$r['status']==='inactive'?'selected':''?>>غير نشط</option></select><button>حفظ</button></form></main>
